#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

int64_t gcd(int64_t val, int64_t other) {
    while (other != 0) {
        int64_t temp = other;
        other = val - (val / other) * other;
        val = temp;
    }
    return val < 0 ? -val : val;
}

int64_t totient(int64_t n) {
    if (n <= 1) {
        return n < 0 ? 0 : n;
    }
    int64_t count = 1;
    for (int64_t k = 2; k < n; k = k + 1) {
        if (gcd(n, k) == 1) {
            count = count + 1;
        }
    }
    return count;
}

int main() {
    int64_t tests[] = {0, 1, 2, 3, 4, 5, 9, 12, 30, 100};
    for (size_t i = 0; i < sizeof(tests)/sizeof(tests[0]); i++) {
        printf("%ld\n", totient(tests[i]));
    }
    return 0;
}

