import java.util.*;

public class Solution {
    public static long totient(long n) {
        long val = n;
        long other = n;
        if (val == other) {
            long result = val;
            long i = 2L;
            while (i * i <= result) {
                if (result % i == 0L) {
                    while (result % i == 0L) {
                        result = result / i;
                    }
                    val = val - val / i;
                }
                i = i + 1L;
            }
            if (result > 1L) {
                val = val - val / result;
            }
            return val;
        }
        return 0L;
    }

    public static void main(String[] args) {
        // Test case 1: n = 1
        System.out.println(totient(1L));

        // Test case 2: n = 2 (prime)
        System.out.println(totient(2L));

        // Test case 3: n = 10
        System.out.println(totient(10L));

        // Test case 4: n = 30
        System.out.println(totient(30L));

        // Test case 5: n = 0 (edge case)
        System.out.println(totient(0L));
    }
}
